# %% ../nbs/11_overlays.ipynb #698fc804
_menu_on = {
    ('&', 'toggle', True): r"""
if (e.target !== el || !el.matches(':popover-open')) return;
[...el.querySelectorAll('a[href], button:not(:disabled)')]
    .find(x => x.getAttribute('aria-disabled') !== 'true' && x.getClientRects().length && getComputedStyle(x).visibility === 'visible')?.focus();""",
    ('&', 'keydown'): r"""
if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key)) return;
const items = [...el.querySelectorAll('a[href], button:not(:disabled)')]
    .filter(x => x.getAttribute('aria-disabled') !== 'true' && x.getClientRects().length && getComputedStyle(x).visibility === 'visible');
if (!items.length) return;
e.preventDefault();
const i = items.indexOf(document.activeElement);
const next = e.key === 'Home' ? 0 : e.key === 'End' ? items.length - 1
    : (i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
items[next].focus();""",
    ('& > [aria-disabled=true]', 'click', True): "e.preventDefault(); e.stopImmediatePropagation()",
    ('&', 'click'): r"""
const item = e.target.closest('a[href], button');
if (!item || !el.contains(item)) return;
if (item.matches(':disabled, [aria-disabled=true]')) { e.preventDefault(); return; }
el.hidePopover();"""}

_menu_css = r"""
[popover][menu] { min-inline-size: min(12rem, calc(100vw - 1rem)); padding: var(--space-3); }
[popover][menu]:popover-open { display: grid; align-content: start; block-size: max-content; }
[menu] > :is(a, button) {
  display: block; inline-size: 100%; text-align: start; padding: var(--space-2) var(--space-1);
  font: inherit; font-weight: var(--weight); color: inherit; text-decoration: none;
  background: none; border: 0; border-radius: var(--radius-1); box-shadow: none;
}
[menu] > :is(a, button):not(:disabled, [aria-disabled=true]):is(:hover, :focus-visible) {
  background: var(--v-3); color: var(--v2);
}
[menu] > :is(a, button)[danger]:not(:disabled, [aria-disabled=true]) { color: var(--v); }
[menu] > :is(a, button):is(:disabled, [aria-disabled=true]) { color: var(--n1); cursor: default; }
[menu] > [hidden] { display: none; }
[menu] > hr { margin-block: var(--space-3); }
"""

@hypelt(sel='[popover][menu]', layer='components', on=_menu_on, css=_menu_css)
def Menu(
    trigger,  # Label text or a configured Button
    *items,   # Buttons, links, and Hr separators
    id=None,  # Panel id; generated when omitted
    **attrs,  # Attributes for the panel
):
    "A button and its popover of ordinary links and actions"
    id = id or unqid()
    if not isinstance(trigger, FT) or trigger.tag != 'button': trigger = Button(trigger, secondary=True)
    return trigger(type='button', popovertarget=id), Popover(*items, menu=True, id=id, **attrs)

